//! Runs every golden case of `testdata/` (generated by `mise run oracle` with the LiteRT
//! reference kernels) and compares nanoglia's outputs with the expected ones.
//!
//! With `NANOGLIA_GOLDEN_DIR` set, runs the cases of that directory instead (absolute path), for
//! cases generated outside the repository, such as the PyTorch export of
//! `tools/oracle/pytorch_export.py`.

use nanoglia::{Encoding, Graph, Target};
mod common;

use common::{Aligned, repo_root};
use nanoglia::core::allocator_api2::alloc::Global;
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};

/// Operators run by the ESP-NN backend (feature `esp-nn`), over all cases.
static ESP_NN_OPERATORS: AtomicUsize = AtomicUsize::new(0);

struct Case {
    dir: PathBuf,
    json: serde_json::Value,
}

/// The directory whose cases run, and whether it is the one of the repository.
fn root() -> (PathBuf, bool) {
    match std::env::var_os("NANOGLIA_GOLDEN_DIR") {
        Some(dir) => (PathBuf::from(dir), false),
        None => (repo_root().join("testdata"), true),
    }
}

fn cases() -> Vec<Case> {
    fn walk(dir: &std::path::Path, out: &mut Vec<Case>) {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                walk(&path, out);
            } else if path.file_name().is_some_and(|n| n == "case.json") {
                let text = std::fs::read_to_string(&path).unwrap();
                let json = serde_json::from_str(&text)
                    .unwrap_or_else(|e| panic!("{}: {e}", path.display()));
                out.push(Case {
                    dir: dir.to_path_buf(),
                    json,
                });
            }
        }
    }
    let mut out = Vec::new();
    walk(&root().0, &mut out);
    out.sort_by(|a, b| a.dir.cmp(&b.dir));
    out
}

fn dtype_size(dtype: &str) -> usize {
    match dtype {
        "int8" | "uint8" | "bool" => 1,
        "int16" => 2,
        "int32" | "uint32" | "float32" => 4,
        "int64" => 8,
        other => panic!("unknown dtype {other}"),
    }
}

/// Largest difference between `actual` and `expected`, in elements of `dtype`.
fn max_diff(dtype: &str, actual: &[u8], expected: &[u8]) -> f64 {
    let size = dtype_size(dtype);
    actual
        .chunks_exact(size)
        .zip(expected.chunks_exact(size))
        .map(|(a, e)| match dtype {
            "int8" => (a[0] as i8 as f64 - e[0] as i8 as f64).abs(),
            "uint8" | "bool" => (a[0] as f64 - e[0] as f64).abs(),
            "int16" => (i16::from_le_bytes([a[0], a[1]]) as f64
                - i16::from_le_bytes([e[0], e[1]]) as f64)
                .abs(),
            "int32" => (i32::from_le_bytes(a.try_into().unwrap()) as f64
                - i32::from_le_bytes(e.try_into().unwrap()) as f64)
                .abs(),
            "uint32" => (u32::from_le_bytes(a.try_into().unwrap()) as f64
                - u32::from_le_bytes(e.try_into().unwrap()) as f64)
                .abs(),
            "int64" => {
                let (a, e) = (
                    i64::from_le_bytes(a.try_into().unwrap()),
                    i64::from_le_bytes(e.try_into().unwrap()),
                );
                a.abs_diff(e) as f64
            }
            "float32" => {
                let (a, e) = (
                    f32::from_le_bytes(a.try_into().unwrap()),
                    f32::from_le_bytes(e.try_into().unwrap()),
                );
                if a == e || (a.is_nan() && e.is_nan()) {
                    0.0
                } else if !a.is_finite() || !e.is_finite() {
                    // Infinities and NaN must match exactly (`f64::max` would drop a NaN
                    // difference).
                    f64::INFINITY
                } else {
                    ((a - e).abs() / e.abs().max(1.0)) as f64
                }
            }
            _ => f64::INFINITY,
        })
        .fold(0.0, f64::max)
}

/// The kernel that must run the operator of the per-op case `name`, for the cases whose kernel is
/// not otherwise pinned down: the int16 cases of operators with a CMSIS-NN kernel, so that the
/// golden data checks CMSIS-NN rather than a fallback, and the int16 activations.
fn expected_kernel(name: &str) -> Option<&'static str> {
    let case = name.strip_prefix("ops/")?;
    if !case.ends_with("_int16") || !cfg!(feature = "int16") {
        return None;
    }
    const KERNELS: &[(&str, &str, bool)] = &[
        ("conv2d_", "cmsis-nn/conv2d_s16", true),
        ("depthwise_conv2d_", "cmsis-nn/depthwise_conv2d_s16", true),
        ("average_pool2d_", "cmsis-nn/average_pool2d_s16", true),
        ("max_pool2d_", "cmsis-nn/max_pool2d_s16", true),
        ("logistic_", "rust/logistic_i16", false),
        ("tanh_", "rust/tanh_i16", false),
    ];
    KERNELS
        .iter()
        .find(|(prefix, _, _)| case.starts_with(prefix))
        .filter(|(_, _, cmsis_nn)| !cmsis_nn || cfg!(feature = "cmsis-nn"))
        .map(|(_, kernel, _)| *kernel)
}

fn run(name: &str, case: &Case) -> Result<(), String> {
    let model = Aligned::read(&repo_root().join(case.json["model"].as_str().unwrap()));
    let graph = Graph::load_in(&[model.bytes()], Encoding::Autodetect, Target::Auto, Global)
        .map_err(|e| format!("load: {e}"))?;
    if let Some(expected) = expected_kernel(name) {
        for i in 0..graph.operator_count() {
            let kernel = graph.kernel_name(i);
            if kernel != Some(expected) {
                return Err(format!("operator {i} runs {kernel:?}, expected {expected}"));
            }
        }
    }
    let esp_nn = (0..graph.operator_count())
        .filter(|&i| {
            graph
                .kernel_name(i)
                .is_some_and(|n| n.starts_with("esp-nn/"))
        })
        .count();
    ESP_NN_OPERATORS.fetch_add(esp_nn, Ordering::Relaxed);
    let mut ctx = graph
        .init_execution_context_in(Global)
        .map_err(|e| format!("context: {e}"))?;
    let tolerance = case.json["tolerance"].as_f64().unwrap_or(0.0);

    for (i, _) in case.json["inputs"].as_array().unwrap().iter().enumerate() {
        let data = std::fs::read(case.dir.join(format!("input_{i}.bin"))).unwrap();
        ctx.set_input(i, &data)
            .map_err(|e| format!("input {i}: {e}"))?;
    }
    ctx.compute().map_err(|e| format!("compute: {e}"))?;
    for (i, spec) in case.json["outputs"].as_array().unwrap().iter().enumerate() {
        let expected = std::fs::read(case.dir.join(format!("output_{i}.bin"))).unwrap();
        let actual = ctx.output(i).map_err(|e| format!("output {i}: {e}"))?;
        if actual.bytes().len() != expected.len() {
            return Err(format!(
                "output {i}: {} bytes, expected {}",
                actual.bytes().len(),
                expected.len()
            ));
        }
        let diff = max_diff(spec["dtype"].as_str().unwrap(), actual.bytes(), &expected);
        if diff > tolerance {
            return Err(format!(
                "output {i}: max diff {diff} > tolerance {tolerance}"
            ));
        }
    }
    Ok(())
}

/// Cases that are expected to fail for now, with the reason. A listed case that passes fails the
/// test too, so the list never goes stale.
const PENDING: &[(&str, &str)] = &[
    // LiteRT's reference FULLY_CONNECTED requantizes in floating point (`round(acc * scale)`),
    // while TFLite Micro and CMSIS-NN use fixed point: deep FC stacks drift by one unit or two.
    // 16x8 layers follow TFLite Micro too (fixed point with a 16-bit multiplier):
    // `ops/fully_connected_per_channel_int16` happens to match LiteRT on its 16 outputs, other
    // data may differ by one.
    (
        "mlperf-tiny/golden/ad01_int8/sample_0",
        "LiteRT float requantization in FULLY_CONNECTED",
    ),
    (
        "mlperf-tiny/golden/ad01_int8/sample_1",
        "LiteRT float requantization in FULLY_CONNECTED",
    ),
    (
        "mlperf-tiny/golden/ad01_int8/sample_2",
        "LiteRT float requantization in FULLY_CONNECTED",
    ),
];

#[test]
fn golden_cases() {
    let cases = cases();
    let (root, testdata) = root();
    let mut failures = Vec::new();
    let mut pending = 0;
    for case in &cases {
        let name = case
            .dir
            .strip_prefix(&root)
            .unwrap_or(&case.dir)
            .display()
            .to_string();
        let reason = PENDING.iter().find(|(n, _)| *n == name).map(|(_, r)| *r);
        match (run(&name, case), reason) {
            (Ok(()), None) => println!("ok       {name}"),
            (Err(e), Some(reason)) => {
                pending += 1;
                println!("pending  {name}: {e} ({reason})");
            }
            (Ok(()), Some(_)) => {
                println!("FIXED    {name}: remove it from PENDING");
                failures.push(name);
            }
            (Err(e), None) => {
                println!("FAIL     {name}: {e}");
                failures.push(name);
            }
        }
    }
    println!(
        "{} cases, {pending} pending, {} failures",
        cases.len(),
        failures.len()
    );
    if testdata {
        assert!(cases.len() > 100, "test data not found");
    } else {
        assert!(!cases.is_empty(), "no case in {}", root.display());
    }
    assert!(failures.is_empty(), "failing cases: {failures:#?}");
    // ESP-NN has no single-rounding mode: the backend then claims nothing.
    if cfg!(feature = "esp-nn") && !cfg!(feature = "single-rounding") {
        let esp_nn = ESP_NN_OPERATORS.load(Ordering::Relaxed);
        println!("{esp_nn} operators run by ESP-NN");
        assert!(esp_nn > 0, "the ESP-NN backend ran no operator");
    }
}
